const items = $input.all();
const inputData = $('Execute Workflow Trigger').first().json;

if (items.length > 0 && items[0].json && items[0].json.order_number) {
  const order = items[0].json;
  const formattedDate = order.estimated_delivery ? new Date(order.estimated_delivery).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : 'soon';

  let reply = `Hello ${order.full_name || 'there'}, your order **${order.order_number}** is currently **${order.status.toUpperCase()}**.\n\n`;
  if (order.carrier && order.tracking_number) {
    reply += `📦 Carrier: ${order.carrier}\n🔍 Tracking Number: ${order.tracking_number}\n📅 Estimated Delivery: ${formattedDate}\n`;
  } else {
    reply += `We are preparing your items for shipment. Estimated delivery: ${formattedDate}.\n`;
  }
  reply += `\nTotal: ${order.total_amount} ${order.currency}. Let us know if you need anything else!`;

  return [{
    json: {
      status: 'success',
      intent_handled: 'order_lookup',
      order_found: true,
      order_data: order,
      reply: reply
    }
  }];
} else {
  const requestedNum = inputData.entities?.order_number || 'your requested order';
  return [{
    json: {
      status: 'not_found',
      intent_handled: 'order_lookup',
      order_found: false,
      reply: `I could not find an active order matching "${requestedNum}". Please verify your order number (e.g. ORD-1001) or provide the email address used during purchase.`
    }
  }];
}
